package com.bank.tracing.context;

import java.util.UUID;

// Carries the correlation/trace ID and current span ID across services.
public class TraceContext {
    private final String correlationId;   // same as traceId; the "case number"
    private final String traceId;
    private final String spanId;
    private final String parentSpanId;

    private TraceContext(String correlationId, String traceId, String spanId, String parentSpanId) {
        this.correlationId = correlationId;
        this.traceId = traceId;
        this.spanId = spanId;
        this.parentSpanId = parentSpanId;
    }

    // Generated ONCE at the edge.
    public static TraceContext createAtEdge() {
        String trace = shortId();
        return new TraceContext(trace, trace, shortId(), null);
    }

    // A child span continues the SAME trace, with this span as parent.
    public TraceContext childSpan() {
        return new TraceContext(correlationId, traceId, shortId(), this.spanId);
    }

    public String getCorrelationId() { return correlationId; }
    public String getTraceId() { return traceId; }
    public String getSpanId() { return spanId; }
    public String getParentSpanId() { return parentSpanId; }

    // W3C traceparent-style header value for propagation over HTTP / Kafka.
    public String toHeader() { return "00-" + traceId + "-" + spanId + "-01"; }

    private static String shortId() { return UUID.randomUUID().toString().substring(0, 8); }
}
