package com.bank.tracing.context;

import java.util.logging.Logger;

// Starts spans and records how long each hop takes.
public class Tracer {
    private static final Logger log = Logger.getLogger(Tracer.class.getName());

    // Start a child span for an operation; returns the new context + start time.
    public Span startSpan(TraceContext parent, String operation) {
        TraceContext ctx = parent.childSpan();
        return new Span(ctx, operation, System.nanoTime());
    }

    public static class Span {
        private final TraceContext context;
        private final String operation;
        private final long startNanos;

        Span(TraceContext context, String operation, long startNanos) {
                this.context = context;
                this.operation = operation
                this.startNanos = startNanos;
        }
        public TraceContext context() { return context; }

        // End the span and record its duration (the latency of this hop).
        public long end() {
            long durMs = (System.nanoTime() - startNanos) / 1_000_000;
            log.info(String.format("SPAN end op=%s trace=%s span=%s parent=%s durationMs=%d",
                    operation, context.getTraceId(), context.getSpanId(),
                    context.getParentSpanId(), durMs));
            return durMs;
        }
    }
}
