package com.bank.tracing.logging;

import com.bank.tracing.context.TraceContext;
import java.util.logging.Logger;

// Every log line is stamped with trace + span IDs → searchable in Kibana.
public class CorrelatedLogger {
    private final Logger delegate;
    public CorrelatedLogger(Class<?> owner) { this.delegate = Logger.getLogger(owner.getName()); }

    public void info(TraceContext ctx, String message) {
        delegate.info(String.format("[trace=%s span=%s] %s",
                ctx.getTraceId(), ctx.getSpanId(), message));
    }
    public void warn(TraceContext ctx, String message) {
        delegate.warning(String.format("[trace=%s span=%s] %s",
                ctx.getTraceId(), ctx.getSpanId(), message));
    }
}
