package com.bank.tracing.service;

import com.bank.tracing.context.*;
import com.bank.tracing.logging.CorrelatedLogger;

public class AccountService {
    private final CorrelatedLogger log = new CorrelatedLogger(AccountService.class);
    private final Tracer tracer = new Tracer();

    public void debitAndCredit(TraceContext parent, String from, String to, String amount) {
        Tracer.Span span = tracer.startSpan(parent, "account.debitAndCredit");
        TraceContext ctx = span.context();
        log.info(ctx, "debit " + from + " credit " + to + " amount " + amount);
        sleep(15); // fast hop
        span.end();
    }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}
