        Tracer.Span span = tracer.startSpan(parent, "fraud.score");
        TraceContext ctx = span.context();
        log.info(ctx, "scoring " + from + " amount " + amount);
        sleep(120); // SLOW hop — this is the latency culprit the trace will reveal
        span.end();
        return 10;
    }
