package com.bank.tracing.service;

import com.bank.tracing.context.*;
import com.bank.tracing.logging.CorrelatedLogger;

public class TransferService {
    private final CorrelatedLogger log = new CorrelatedLogger(TransferService.class);
    private final Tracer tracer = new Tracer();
    private final AccountService accountService = new AccountService();
    private final FraudService fraudService = new FraudService();

    public void transfer(TraceContext parent, String from, String to, String amount) {
        Tracer.Span span = tracer.startSpan(parent, "transfer.transfer");
        TraceContext ctx = span.context();
        log.info(ctx, "received transfer " + from + " -> " + to + " amount " + amount);

        // Downstream calls continue the SAME trace as child spans.
        int risk = fraudService.score(ctx, from, amount);   // slow hop
        if (risk < 80) accountService.debitAndCredit(ctx, from, to, amount);

        // Async notification: propagate trace context via message header.
        String kafkaHeaderTraceparent = ctx.childSpan().toHeader();
        log.info(ctx, "published notification event with traceparent=" + kafkaHeaderTraceparent);
        span.end();
    }
}
