package com.bank.tracing.service;

import com.bank.tracing.context.TraceContext;
import com.bank.tracing.logging.CorrelatedLogger;

// The edge: generates the correlation/trace ID ONCE and starts the flow.
public class GatewayService {
    private final CorrelatedLogger log = new CorrelatedLogger(GatewayService.class);
    private final TransferService transferService = new TransferService();

    public String handleTransfer(String from, String to, String amount) {
        TraceContext ctx = TraceContext.createAtEdge();   // generate ONCE
        log.info(ctx, "GATEWAY received transfer; correlationId=" + ctx.getCorrelationId());
        transferService.transfer(ctx, from, to, amount);
        log.info(ctx, "GATEWAY returning response for correlationId=" + ctx.getCorrelationId());
        return ctx.getCorrelationId();
    }
}
