package com.bank.tracing;

import com.bank.tracing.service.GatewayService;
import java.util.logging.*;

public class TracingDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(TracingDemo.class.getName());

        GatewayService gateway = new GatewayService();
        // One transfer flows: gateway → transfer → fraud(slow) + account → async notify.
        String correlationId = gateway.handleTransfer("SAV2001", "CUR3001", "50000");

        log.info("To debug, search centralized logs (Kibana) for correlationId=" + correlationId);
        log.info("The trace waterfall (Jaeger) shows fraud.score was the slow hop (~120ms).");
    }
}

